package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/pbkdf2"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"strings"
	"testing"
)

// Generated by sdk-js/e2ee.js primitives with:
// password=correct horse battery staple
// salt=000102...0f, nonce=000102...0b, iterations=310000
// plaintext=Ask4Me E2EE test vector
const (
	e2eeTestVectorSalt  = "AAECAwQFBgcICQoLDA0ODw"
	e2eeTestVectorToken = "enc:v1:AAECAwQFBgcICQoLShTpgXdxErUQILyQ_bp44flBr_TuPYPM7mRWF9xPV_CzoL6ODmd3"
	e2eeTestPassword    = "correct horse battery staple"
	e2eeTestPlain       = "Ask4Me E2EE test vector"
)

func decryptE2EETestVector(t *testing.T, token, password, saltB64 string, iterations int) (string, error) {
	t.Helper()
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(token, e2eeTokenPrefix))
	if err != nil {
		return "", err
	}
	if len(raw) < 12+16 {
		return "", errShortToken
	}
	salt, err := base64.RawURLEncoding.DecodeString(saltB64)
	if err != nil {
		return "", err
	}
	key, err := pbkdf2.Key(sha256.New, password, salt, iterations, 32)
	if err != nil {
		return "", err
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}
	pt, err := gcm.Open(nil, raw[:12], raw[12:], []byte(e2eeAAD))
	if err != nil {
		return "", err
	}
	return string(pt), nil
}

var errShortToken = errors.New("token too short")

func TestE2EETestVector(t *testing.T) {
	got, err := decryptE2EETestVector(t, e2eeTestVectorToken, e2eeTestPassword, e2eeTestVectorSalt, defaultE2EEIterations)
	if err != nil {
		t.Fatalf("decrypt vector: %v", err)
	}
	if got != e2eeTestPlain {
		t.Fatalf("plaintext = %q, want %q", got, e2eeTestPlain)
	}
}

func TestE2EETamperFails(t *testing.T) {
	token := []byte(e2eeTestVectorToken)
	token[len(token)-1] ^= 0x01
	if _, err := decryptE2EETestVector(t, string(token), e2eeTestPassword, e2eeTestVectorSalt, defaultE2EEIterations); err == nil {
		t.Fatal("expected tampered token to fail")
	}
}

func TestE2EEConfigNormalize(t *testing.T) {
	cfg := Config{
		BaseURL: "https://example.com",
		APIKey:  "key",
		E2EE:    E2EEConfig{Enabled: true},
	}
	if err := cfg.normalize(); err != nil {
		t.Fatalf("normalize: %v", err)
	}
	if cfg.E2EE.KDFIterations != defaultE2EEIterations {
		t.Fatalf("iterations = %d", cfg.E2EE.KDFIterations)
	}
	if !cfg.E2EE.encryptAnswersDefault() {
		t.Fatal("answers default should be true")
	}

	badHTTP := Config{BaseURL: "http://example.com", APIKey: "key", E2EE: E2EEConfig{Enabled: true}}
	if err := badHTTP.normalize(); err == nil {
		t.Fatal("expected error for non-local http base_url")
	}

	localHTTP := Config{BaseURL: "http://127.0.0.1:8080", APIKey: "key", E2EE: E2EEConfig{Enabled: true}}
	if err := localHTTP.normalize(); err != nil {
		t.Fatalf("localhost http should be allowed: %v", err)
	}

	badIterations := Config{
		BaseURL: "https://example.com",
		APIKey:  "key",
		E2EE:    E2EEConfig{Enabled: true, KDFIterations: 10},
	}
	if err := badIterations.normalize(); err == nil {
		t.Fatal("expected error for too few iterations")
	}
}

func TestNormalizeE2EE(t *testing.T) {
	cfg := Config{
		BaseURL: "https://example.com",
		APIKey:  "key",
		E2EE:    E2EEConfig{Enabled: true},
	}
	if err := cfg.normalize(); err != nil {
		t.Fatalf("normalize: %v", err)
	}
	s := &server{cfg: cfg}

	ar := askRequest{
		Body: e2eeTestVectorToken,
		E2EE: &e2eeSpec{Enabled: true, Salt: e2eeTestVectorSalt},
	}
	if err := s.normalizeE2EE(&ar); err != nil {
		t.Fatalf("normalize e2ee: %v", err)
	}
	if ar.E2EE.Iterations != defaultE2EEIterations || !s.e2eeAnswers(ar) {
		t.Fatalf("e2ee defaults = %+v answers=%v", ar.E2EE, s.e2eeAnswers(ar))
	}

	missingSalt := askRequest{Body: e2eeTestVectorToken, E2EE: &e2eeSpec{Enabled: true}}
	if err := s.normalizeE2EE(&missingSalt); err == nil {
		t.Fatal("expected missing salt error")
	}

	plainBody := askRequest{Body: "plaintext", E2EE: &e2eeSpec{Enabled: true, Salt: e2eeTestVectorSalt}}
	if err := s.normalizeE2EE(&plainBody); err == nil {
		t.Fatal("expected plaintext body error")
	}

	disabled := &server{cfg: Config{MultiUser: MultiUserConfig{}, E2EE: E2EEConfig{}}}
	withE2EE := askRequest{Body: e2eeTestVectorToken, E2EE: &e2eeSpec{Enabled: true, Salt: e2eeTestVectorSalt}}
	if err := disabled.normalizeE2EE(&withE2EE); err == nil {
		t.Fatal("expected e2ee disabled error")
	}

	// E2EE is opt-in per request: the same server still accepts plaintext.
	plain := askRequest{Body: "plaintext"}
	if err := s.normalizeE2EE(&plain); err != nil {
		t.Fatalf("plaintext request should be allowed: %v", err)
	}
	if s.e2eeActive(plain) {
		t.Fatal("plaintext request must not be treated as encrypted")
	}
	optionalEncrypted := askRequest{Body: e2eeTestVectorToken, E2EE: &e2eeSpec{Enabled: true, Salt: e2eeTestVectorSalt}}
	if err := s.normalizeE2EE(&optionalEncrypted); err != nil {
		t.Fatalf("encrypted request should be allowed: %v", err)
	}
	if !s.e2eeActive(optionalEncrypted) {
		t.Fatal("encrypted request should be active")
	}
}

func TestE2EENotificationText(t *testing.T) {
	cfg := Config{
		BaseURL: "https://example.com",
		APIKey:  "key",
		E2EE:    E2EEConfig{Enabled: true},
	}
	if err := cfg.normalize(); err != nil {
		t.Fatalf("normalize: %v", err)
	}
	s := &server{cfg: cfg}

	encrypted := askRequest{
		Title: e2eeTestVectorToken,
		Body:  e2eeTestVectorToken,
		E2EE:  &e2eeSpec{Enabled: true, Salt: e2eeTestVectorSalt},
	}
	if got := s.notificationTitle(encrypted); got != e2eeNotificationTitle {
		t.Fatalf("title = %q", got)
	}
	if got := s.notificationBody(encrypted); got != e2eeNotificationBody {
		t.Fatalf("body = %q", got)
	}

	plainTitle := encrypted
	plainTitle.Title = "Approval"
	if got := s.notificationTitle(plainTitle); got != "Approval" {
		t.Fatalf("plain title = %q", got)
	}
}

func TestE2EETokenDetection(t *testing.T) {
	if !isE2EEToken(e2eeTestVectorToken) {
		t.Fatal("expected valid token")
	}
	for _, v := range []string{"", "plain", "enc:v1:", "enc:v1:abc"} {
		if isE2EEToken(v) {
			t.Fatalf("unexpected token: %q", v)
		}
	}
}

func TestE2EEPageTemplate(t *testing.T) {
	var buf bytes.Buffer
	err := pageTpl.Execute(&buf, htmlData{
		Title:          "title",
		Body:           e2eeTestVectorToken,
		Done:           false,
		Token:          "token",
		RequestID:      "req_test",
		JsonForms:      false,
		E2EE:           true,
		E2EESalt:       e2eeTestVectorSalt,
		E2EEIterations: defaultE2EEIterations,
		E2EEAnswers:    true,
	})
	if err != nil {
		t.Fatalf("execute template: %v", err)
	}
	html := buf.String()
	for _, want := range []string{
		`id="e2ee-unlock"`,
		`/static/e2ee.bundle.js`,
		`Ask4MeE2EE`,
		e2eeTestVectorSalt,
		"E2EE_ANSWERS = true",
		e2eeTestVectorToken,
	} {
		if !strings.Contains(html, want) {
			t.Fatalf("page missing %q", want)
		}
	}

	buf.Reset()
	if err := pageTpl.Execute(&buf, htmlData{
		Title: "title",
		Body:  "body",
		Done:  true,
		Token: "token",
		E2EE:  true,
	}); err != nil {
		t.Fatalf("execute done template: %v", err)
	}
	if !strings.Contains(buf.String(), "Submitted.") {
		t.Fatal("done page should show Submitted. outside the locked content")
	}
}
